pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 value, bytes memory data) public {
        // Restrict to the admissible domain: sendMoney is onlyOwner, so caller must be owner.
        // Also the self-call must trigger withdrawAll, so data should be abi.encodeWithSignature("withdrawAll()")
        // but we want the fuzzer to reach a low-level call that exactly attempts to call withdrawAll.
        // Since the bug manifests when the modifier on withdrawAll is empty, the self-call with withdrawAll selector is the target.
        // We'll direct c to call itself via sendMoney. The owner makes the call.
        vm.assume(value <= address(c).balance + value); // prevent overflow in funding (safe assumption)
        vm.deal(address(c), value); // ensure c has enough balance for the transfer
        vm.prank(c.owner());
        bool ok;
        try c.sendMoney(address(c), value, abi.encodeWithSignature("withdrawAll()")) {
            ok = true;
        } catch {
            ok = false;
        }
        // The reference C protects withdrawAll with onlyOwner, so a call from c (not the owner) via sendMoney reverts.
        // The buggy version has an empty onlyOwner, so the call succeeds.
        assertTrue(!ok);
    }
}

