pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, address attacker, bytes memory data) public {
        // 1. Bound amount to avoid overflow and keep it admissible
        amount = bound(amount, 1, address(c).balance + 1);
        vm.assume(attacker != address(0) && attacker != address(c));
        vm.assume(attacker != c.owner());

        // 2. Setup: fund the contract
        vm.deal(address(c), amount);

        // 3. Attacker (non-owner) tries to call sendMoney, which should revert in reference
        // but succeeds in mutant due to empty modifier, potentially changing owner
        vm.prank(attacker);
        bool ok = false;
        try c.sendMoney(address(0xdead), 0, data) {
            ok = true;
        } catch {
            ok = false;
        }

        // 4. Assert: In reference, ok must be false (revert) for any non-owner.
        // In mutant, ok can be true, and the attacker could have changed owner.
        // Rule: If sendMoney does not revert, the owner must remain the original.
        assertTrue(!ok || c.owner() == address(this));
    }
}

